def countNearMatches(text, pattern):
    n, m = len(text), len(pattern)
    if m > n:
        return 0

    def zfunc(s):
        L = len(s)
        z = [0] * L
        l = r = 0
        for i in range(1, L):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < L and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l, r = i, i + z[i]
        return z

    zf = zfunc(pattern + '#' + text)
    zb = zfunc(pattern[::-1] + '#' + text[::-1])
    count = 0
    for i in range(n - m + 1):
        pre = zf[m + 1 + i]
        end = i + m - 1
        suf = zb[m + 1 + (n - 1 - end)]
        if pre + suf >= m - 1:
            count += 1
    return count
